async fn send_with_path(
    address: SocketAddr,
    body: impl Into<reqwest::Body> + Send + 'static,
    headers: HeaderMap,
    path: &str,
) -> u16 {
    timeout(
        HTTP_REQUEST_TIMEOUT,
        reqwest::Client::new()
            .post(format!("http://{address}{path}"))
            .headers(headers)
            .body(body)
            .send(),
    )
    .await
    .expect("send_with_path request timed out")
    .unwrap()
    .status()
    .as_u16()
}

