    .unwrap();

    assert_eq!(
        200,
        send_with_path(addr, body.clone(), HeaderMap::new(), DD_API_LOGS_V1_PATH).await
    );

    assert_eq!(
        503,
        send_with_path(addr, body.clone(), HeaderMap::new(), DD_API_LOGS_V1_PATH).await
    );
    drop(rx);
}

